from config import MAX_RETRIES, TIMEOUT_SEC


def send(payload, attempts=0):
    """返回 (ok, attempts_used)。超过 MAX_RETRIES 次即放弃。"""
    while attempts < MAX_RETRIES:
        attempts += 1
        if payload.get("ok"):
            return True, attempts
    return False, attempts

