from decimal import Decimal, ROUND_HALF_UP


def to_cents(amount):
    """把金额（元）转为整数分，四舍五入避免浮点截断误差。"""
    return int((Decimal(str(amount)) * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))

