_opened = []


def open_many(paths):
    handles = []
    for p in paths:
        h = open(p, "w", encoding="utf-8")
        _opened.append(h)
        handles.append(h)
    return handles


def close_many(handles):
    for h in handles:
        if not h.closed:
            h.close()


def pending():
    return len([h for h in _opened if not h.closed])

from opener import open_many, close_many, pending


def write_all(paths, content):
    hs = open_many(paths)
    try:
        for h in hs:
            h.write(content)
            h.flush()
    finally:
        close_many(hs)
    return pending()
